-- Server-originated player telemetry (only events received by this API are recorded).
-- event_id is an idempotency key generated by the Roblox server script.
CREATE TABLE IF NOT EXISTS player_events (
  event_id TEXT PRIMARY KEY NOT NULL,
  batch_id TEXT NOT NULL,
  event_type TEXT NOT NULL CHECK (event_type IN ('join', 'leave')),
  place_id TEXT NOT NULL,
  universe_id TEXT,
  job_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  username TEXT NOT NULL,
  occurred_at INTEGER NOT NULL,
  received_at INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_player_events_place_occurred
  ON player_events(place_id, occurred_at DESC);
CREATE INDEX IF NOT EXISTS idx_player_events_user_occurred
  ON player_events(user_id, occurred_at DESC);
CREATE INDEX IF NOT EXISTS idx_player_events_batch
  ON player_events(batch_id);

-- A projection of the latest event state. Active players are queried from this table;
-- the event log above remains the append-only record for audit/troubleshooting.
CREATE TABLE IF NOT EXISTS player_sessions (
  place_id TEXT NOT NULL,
  job_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  username TEXT NOT NULL,
  joined_at INTEGER NOT NULL,
  last_event_at INTEGER NOT NULL,
  left_at INTEGER,
  is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
  PRIMARY KEY (place_id, job_id, user_id)
);
CREATE INDEX IF NOT EXISTS idx_player_sessions_active
  ON player_sessions(place_id, is_active, joined_at DESC);
CREATE INDEX IF NOT EXISTS idx_player_sessions_user
  ON player_sessions(user_id, last_event_at DESC);
